#!/bin/bash
export AGENT_BROWSER_SESSION=nl-quota
ab() { agent-browser "$@"; }
SHIM='window.__dead=new Set(); window.__calls=[]; const rf=window.fetch.bind(window); window.fetch=async(u,o)=>{ const s=String(u); if(!s.includes("generativelanguage")) return rf(u,o); const m=s.match(/models\/([^:]+)/)[1]; window.__calls.push(m); await new Promise(r=>setTimeout(r,150)); if(window.__dead.has(m)||window.__dead.has("*")) return new Response(JSON.stringify({error:{code:429,message:"You exceeded your current quota",details:[{violations:[{quotaId:"GenerateRequestsPerDayPerProjectPerModel-FreeTier"}]}]}}),{status:429}); const body=JSON.parse(o.body); const wantsJson=JSON.stringify(body).includes("JSON"); const text=wantsJson?JSON.stringify({title:"ตอนจริง",summary:"สรุป",terms:[]}):"คำแปลทดสอบ"; return new Response(JSON.stringify({candidates:[{content:{parts:[{text}]},finishReason:"STOP"}],usageMetadata:{totalTokenCount:10}}),{status:200}); };'
ab open http://localhost:8765/ >/dev/null; ab wait --load networkidle >/dev/null
ab eval 'localStorage.clear(); localStorage.setItem("nl:ai", JSON.stringify({provider:"gemini",model:"gemini-3.5-flash",keys:{gemini:"test-key-fake"},base:"",fallback:true,models:{},parallel:1,paid:false})); location.reload(); 1' >/dev/null; sleep 1.5
ab eval "(async()=>{ $SHIM window.prompt=()=>'โควต้า'; document.querySelector('[data-action=new-project]').click(); await new Promise(r=>setTimeout(r,400)); const t=document.querySelector('#pasteIn'); t.value=[1,2,3,4,5,6].map(i=>'Chapter '+i+'\nText '+i+'.').join('\n\n'); document.querySelector('[data-action=paste-import]').click(); await new Promise(r=>setTimeout(r,300)); document.querySelector('[data-action=confirm-import]').click(); await new Promise(r=>setTimeout(r,300)); return document.querySelectorAll('tbody tr').length })()"
echo "--- A: first model quota mid-run"; ab eval "(async()=>{ document.querySelector('[data-action=translate-todo]').click(); for(let i=0;i<60;i++){ await new Promise(r=>setTimeout(r,250)); if(/เสร็จ [2-9]/.test(document.querySelector('#runner').innerText)) break; } window.__dead.add('gemini-3.5-flash'); for(let i=0;i<200;i++){ await new Promise(r=>setTimeout(r,250)); if(/แปลเสร็จ/.test(document.querySelector('#runner').innerText)) break; } const log=document.querySelector('#runner').innerText; return {head:log.split('\n')[0], switched:/สลับ|โควตา/.test(log), models:[...new Set(window.__calls)], logTail:log.split('\n').slice(-3)} })()"
echo "--- B: all models quota"; ab eval "(async()=>{ document.querySelector('[data-action=close-runner]')?.click(); const p=document.querySelectorAll('[data-action=translate-one]'); window.__dead.add('*'); window.__calls.length=0; document.querySelector('[data-action=select-all]').click(); await new Promise(r=>setTimeout(r,200)); document.querySelector('[data-action=translate-selected]').click(); for(let i=0;i<200;i++){ await new Promise(r=>setTimeout(r,250)); if(/แปลเสร็จ/.test(document.querySelector('#runner').innerText)) break; } const log=document.querySelector('#runner').innerText; const badges={}; [...document.querySelectorAll('tbody .badge')].forEach(b=>badges[b.innerText]=(badges[b.innerText]||0)+1); return {head:log.split('\n')[0], tail:log.split('\n').slice(-2), triedModels:[...new Set(window.__calls)].length, calls:window.__calls.length, badges, errorText:document.querySelector('tbody [style*=accent]')?.innerText.slice(0,120)} })()"
echo "--- AI page after"; ab eval "(async()=>{ document.querySelector('#tabs [data-view=ai]').click(); await new Promise(r=>setTimeout(r,300)); const p=[...document.querySelectorAll('main p')].find(x=>x.innerText.includes('โควตาฟรีวันนี้หมด')); return {note:p?.innerText.slice(0,160), pill:document.querySelector('#aiPill').innerText} })()"
ab errors; ab close >/dev/null
